import React, { useState, useEffect, useRef } from 'react';
import * as tf from '@tensorflow/tfjs';
import * as tmImage from '@teachablemachine/image';
import './App.css';



const URL = "https://teachablemachine.withgoogle.com/models/B-u58ABRL/";

function App() {
  const [resultText, setResultText] = useState("여기에 결과가 표시됩니다.");
  const [isAnalyzing, setIsAnalyzing] = useState(true);
  const [isHighConfidence, setIsHighConfidence] = useState(false);
  const [isStarted, setIsStarted] = useState(false);

  const webcamContainerRef = useRef(null);
  const webcamRef = useRef(null);
  const modelRef = useRef(null);
  const requestRef = useRef(null);

  // 컴포넌트가 언마운트될 때 웹캠 및 애니메이션 루프 종료
  useEffect(() => {
    return () => {
      if (requestRef.current) {
        cancelAnimationFrame(requestRef.current);
      }
      if (webcamRef.current) {
        webcamRef.current.stop();
      }
    };
  }, []);

  const init = async () => {
    if (isStarted) return; // 이미 시작된 경우 중복 실행 방지
    setIsStarted(true);
    setResultText("모델 로딩 중...");

    const modelURL = URL + "model.json";
    const metadataURL = URL + "metadata.json";

    try {
      // 모델 로드
      modelRef.current = await tmImage.load(modelURL, metadataURL);
      
      // 웹캠 설정
      const flip = true; 
      const webcam = new tmImage.Webcam(240, 240, flip); 
      await webcam.setup(); 
      await webcam.play();
      webcamRef.current = webcam;

      // 웹캠 캔버스 주입
      if (webcamContainerRef.current) {
        webcamContainerRef.current.innerHTML = ""; 
        webcamContainerRef.current.appendChild(webcam.canvas);
      }

      setResultText("준비 완료! 손을 보여주세요.");
      setIsAnalyzing(false);

      // 루프 시작
      requestRef.current = requestAnimationFrame(loop);
    } catch (error) {
      console.error("AI 카메라 시작 중 오류 발생:", error);
      setResultText("카메라를 시작할 수 없습니다.");
      setIsStarted(false);
    }
  };

  const loop = async () => {
    if (webcamRef.current) {
      webcamRef.current.update(); 
      await predict();
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const predict = async () => {
    if (!modelRef.current || !webcamRef.current) return;

    const prediction = await modelRef.current.predict(webcamRef.current.canvas);
    const maxPredictions = modelRef.current.getTotalClasses();
    
    let maxProbability = -1;
    let bestClassName = "";
    let duplicateMax = false;

    // 모든 예측값을 순회하며 확률 최댓값 찾기
    for (let i = 0; i < maxPredictions; i++) {
      const currentProb = prediction[i].probability;
      
      if (currentProb > maxProbability) {
        maxProbability = currentProb;
        bestClassName = prediction[i].className;
        duplicateMax = false;
      } else if (currentProb === maxProbability && maxProbability > 0) {
        duplicateMax = true;
      }
    }

    const percent = (maxProbability * 100).toFixed(0);

    // 확률이 모두 동일하거나 인식이 낮을 경우 처리
    if (duplicateMax || maxProbability <= 0.1) {
      setResultText("분석 중...");
      setIsAnalyzing(true);
      setIsHighConfidence(false);
    } 
    // 독보적인 최댓값이 발견된 정상 상태 처리
    else {
      setResultText(`${bestClassName} (${percent}%)`);
      setIsAnalyzing(false);
      
      // 50%가 넘으면 강조 효과 적용
      if (Number(percent) > 50) {
        setIsHighConfidence(true);
      } else {
        setIsHighConfidence(false);
      }
    }
  };

  // 동적 클래스 네임 결정
  let resultClassName = "result-display";
  if (isAnalyzing) resultClassName += " analyzing";
  if (isHighConfidence) resultClassName += " high-confidence";

  return (
    <div className="container">
      <h1>Teachable Machine 가위바위보</h1>
      <p className="subtitle">아래 손 모양 가이드를 참고하여 카메라 앞에서 흉내 내 보세요!</p>

      

      <button 
        className="start-btn" 
        type="button" 
        onClick={init}
        disabled={isStarted}
      >
        {isStarted ? "AI 카메라 작동 중" : "AI 카메라 시작하기"}
      </button>

      <div id="webcam-container" ref={webcamContainerRef}></div>

      <div id="label-container">
        <div className={resultClassName}>
          {resultText}
        </div>
      </div>
    </div>
  );
}

export default App;